const AboutRoute = AboutRouteImport.update({
  id: '/about',
  path: '/about',
  getParentRoute: () => rootRouteImport,
} as any)
const IndexRoute = IndexRouteImport.update({
  id: '/',
  path: '/',
  getParentRoute: () => rootRouteImport,
} as any)
const ApiCounterRoute = ApiCounterRouteImport.update({
  id: '/api/counter',
  path: '/api/counter',
  getParentRoute: () => rootRouteImport,
} as any)
const ApiCounterIncrementRoute = ApiCounterIncrementRouteImport.update({
  id: '/increment',
  path: '/increment',
  getParentRoute: () => ApiCounterRoute,
} as any)

export interface FileRoutesByFullPath {
  '/': typeof IndexRoute
  '/about': typeof AboutRoute
  '/api/counter': typeof ApiCounterRouteWithChildren
  '/api/counter/increment': typeof ApiCounterIncrementRoute
}
export interface FileRoutesByTo {
  '/': typeof IndexRoute
  '/about': typeof AboutRoute
  '/api/counter': typeof ApiCounterRouteWithChildren
  '/api/counter/increment': typeof ApiCounterIncrementRoute
}
export interface FileRoutesById {
  __root__: typeof rootRouteImport
  '/': typeof IndexRoute
  '/about': typeof AboutRoute
  '/api/counter': typeof ApiCounterRouteWithChildren
  '/api/counter/increment': typeof ApiCounterIncrementRoute
}
export interface FileRouteTypes {
  fileRoutesByFullPath: FileRoutesByFullPath
  fullPaths: '/' | '/about' | '/api/counter' | '/api/counter/increment'
  fileRoutesByTo: FileRoutesByTo
  to: '/' | '/about' | '/api/counter' | '/api/counter/increment'
  id: '__root__' | '/' | '/about' | '/api/counter' | '/api/counter/increment'
  fileRoutesById: FileRoutesById
}
export interface RootRouteChildren {
  IndexRoute: typeof IndexRoute
  AboutRoute: typeof AboutRoute
  ApiCounterRoute: typeof ApiCounterRouteWithChildren
}

declare module '@tanstack/react-router' {
  interface FileRoutesByPath {
    '/about': {
      id: '/about'
      path: '/about'
      fullPath: '/about'
      preLoaderRoute: typeof AboutRouteImport
      parentRoute: typeof rootRouteImport
